import { Activity } from 'react';

function Tabs({ tab }) {
  return (
    <>
      <Activity mode={tab === 'edit' ? 'visible' : 'hidden'}>
        <Editor />
      </Activity>
      <Activity mode={tab === 'preview' ? 'visible' : 'hidden'}>
        <Preview />
      </Activity>
    </>
  );
}
